({5*cos(\t)+14}, {10*sin(\t)});
\legend{$z=0$: $\frac{x^2}{4}+\frac{y^2}{25}=1$,
        $y=0$: $\frac{x^2}{4}+\frac{z^2}{100}=1$,
        $x=0$: $\frac{y^2}{25}+\frac{z^2}{100}=1$}
\end{axis}
\end{tikzpicture}
\end{document}

